mod indicators;

use indicators::{Percentage, ProgressDisplay};

fn parse_progress_arg(raw: &str) -> i32 {
    let trimmed = raw.trim_start();
    let bytes = trimmed.as_bytes();
    let mut end = 0usize;

    if let Some(first) = bytes.first() {
        if *first == b'+' || *first == b'-' {
            end = 1;
        }
    }

    let digits_start = end;
    while end < bytes.len() && bytes[end].is_ascii_digit() {
        end += 1;
    }

    if end == digits_start {
        panic!("stoi");
    }

    trimmed[..end].parse::<i32>().unwrap_or_else(|_| panic!("stoi"))
}

fn main() {
    let mut display = ProgressDisplay::new(200);
    let progress = std::env::args()
        .nth(1)
        .map_or(150, |raw| parse_progress_arg(&raw));

    display.update(progress);
    println!("{}", display.display());

    display.increment(25);
    println!("{}", display.display());

    let pct1 = Percentage::new(0.15_f32, 1);
    let pct2 = Percentage::new(0.35_f32, 2);
    let pct3 = Percentage::new(0.65_f32, 3);

    println!("{}", pct1.str());
    println!("{}", pct2.str());
    println!("{}", pct3.str());
}

